def multi_reward_group_normalized_advantages(
    rewards_by_name,
    advantage_groups,
    weights,
    eps=1e-4,
    renormalize_combined=False,
):
    """Normalize each reward inside prompt groups, then combine fixed objectives."""
    rewards_by_name = {name: np.asarray(value, dtype=np.float64) for name, value in rewards_by_name.items()}
    weights = {name: float(value) for name, value in weights.items()}
    if not rewards_by_name:
        raise ValueError("multi-reward advantages require at least one reward")
    if set(weights) != set(rewards_by_name):
        raise ValueError("multi-reward advantage weight keys must match reward keys")
    if any(not np.isfinite(value) or value <= 0 for value in weights.values()):
        raise ValueError("multi-reward advantage weights must be finite and positive")
    if not np.isfinite(float(eps)) or float(eps) <= 0:
        raise ValueError("multi-reward advantage eps must be finite and positive")

    groups = np.asarray(advantage_groups)
    first_shape = next(iter(rewards_by_name.values())).shape
    if len(first_shape) == 0 or first_shape[0] != groups.shape[0]:
        raise ValueError("multi-reward advantages require one reward row per group row")
    if any(value.shape != first_shape for value in rewards_by_name.values()):
        raise ValueError("all multi-reward arrays must have matching shapes")

    weight_sum = sum(weights.values())
    normalized_weights = {name: value / weight_sum for name, value in weights.items()}
    per_reward = {
        name: group_mean_group_std_advantages(groups, rewards, eps=float(eps))
        for name, rewards in rewards_by_name.items()
    }
    combined = np.zeros(first_shape, dtype=np.float64)
    for name, advantages in per_reward.items():
        combined += normalized_weights[name] * advantages
    if renormalize_combined:
        combined = combined - combined.mean(axis=0, keepdims=True)
        combined = combined / (combined.std(axis=0, keepdims=True) + float(eps))

def covariance_guidance_scores(samples, config):
    """Select one terminal scalar per trajectory for covariance estimation."""
    source = str(
        getattr(
            config.train,
            "covariance_guidance_reward_source",
            "weighted_reward",
        )
    )
    if source == "weighted_reward":
        return samples["rewards"]["ori_avg"]
    if source != "combined_multi_reward_advantage":
        raise ValueError(
            "train.covariance_guidance_reward_source must be "
            "'weighted_reward' or 'combined_multi_reward_advantage'"
        )
    if not multi_reward_advantage_enabled(config):
        raise ValueError(
            "combined_multi_reward_advantage covariance requires "
            "train.multi_reward_advantage.enabled=True"
        )
    advantages = torch.as_tensor(samples["advantages"])
    if advantages.ndim != 2 or advantages.shape[1] == 0:
        raise ValueError("multi-reward covariance requires [batch, timestep] advantages")
    if not torch.allclose(
        advantages,
        advantages[:, :1].expand_as(advantages),
        atol=1e-6,
        rtol=1e-6,
    ):
        raise ValueError(
            "combined multi-reward covariance expects timestep-invariant scores"
        )
    return advantages[:, 0]

