        name: np.repeat(
            np.asarray(gathered_rewards[name])[:, None],
            timestep_count,
            axis=1,
        )
        for name in objective_weights
    }
    advantages, _, multi_reward_advantage_metrics = (
        multi_reward_group_normalized_advantages(
