def clip_nft_advantages(advantages: torch.Tensor, adv_clip_max: float, adv_mode: Optional[str] = "all") -> torch.Tensor:
    """Apply DiffusionNFT advantage clipping and optional mode transforms."""
    advantages_clip = torch.clamp(advantages, -adv_clip_max, adv_clip_max)
    if adv_mode == "positive_only":
        advantages_clip = torch.clamp(advantages_clip, 0, adv_clip_max)

